def estadisticas(numeros):
    return min(numeros), max(numeros), sum(numeros)/len(numeros)

minimo, maximo, promedio = estadisticas([10, 20, 30])
print(minimo)     # 10
print(maximo)     # 30
print(promedio)   # 20.0

persona = {"nombre": "Ana"}

persona["edad"] = 25          # agregar
persona["nombre"] = "Ana María"   # modificar

del persona["edad"]           # eliminar

print(persona)   # {'nombre': 'Ana María'}

persona = {"nombre": "Ana", "edad": 25, "ciudad": "Madrid"}

# Claves
for k in persona:
    print(k)

# Valores
for v in persona.values():
    print(v)

# Pares
for k, v in persona.items():
    print(f"{k}: {v}")

